/**
 * Checkbox — a two- or three-state boolean control.
 *
 * App-entry setup (one time, e.g. main.tsx):
 *   import "@patternfly/react-core/dist/styles/base.css"; // PF6 base FIRST
 *   import "@golden-passport/ds-patternfly/styles";       // lib styles LAST
 *   // …then wrap your root in <ThemeProvider brand={…}>.
 */
import { useState } from "react";
import { Checkbox } from "@golden-passport/ds-patternfly";

export function States() {
  const [checked, setChecked] = useState(true);

  return (
    <div style={{ display: "grid", gap: 12 }}>
      <Checkbox id="cb-1" label="Default" isChecked={checked} onChange={(_, v) => setChecked(v)} />
      <Checkbox id="cb-2" label="Disabled" isDisabled isChecked={false} onChange={() => {}} />
      <Checkbox id="cb-3" label="Disabled + checked" isDisabled isChecked onChange={() => {}} />
      <Checkbox
        id="cb-4"
        label="Indeterminate (parent of mixed children)"
        isChecked={null}
        onChange={() => {}}
      />
    </div>
  );
}

export function WithDescription() {
  const [checked, setChecked] = useState(true);

  return (
    <Checkbox
      id="cb-5"
      label="Send weekly summary"
      description="A digest of activity from the last 7 days."
      isChecked={checked}
      onChange={(_, v) => setChecked(v)}
    />
  );
}

export function MultiSelectGroup() {
  const [email, setEmail] = useState(true);
  const [sms, setSms] = useState(false);

  return (
    <fieldset style={{ border: "none", margin: 0, padding: 0 }}>
      <legend style={{ padding: 0, marginBottom: 8, color: "var(--gp-color-text-regular)" }}>
        Notify me about
      </legend>
      <div style={{ display: "grid", gap: 8 }}>
        <Checkbox id="cb-6" label="Email" isChecked={email} onChange={(_, v) => setEmail(v)} />
        <Checkbox id="cb-7" label="SMS" isChecked={sms} onChange={(_, v) => setSms(v)} />
      </div>
    </fieldset>
  );
}

export default function CheckboxExample() {
  return (
    <div style={{ display: "grid", gap: 24 }}>
      <States />
      <WithDescription />
      <MultiSelectGroup />
    </div>
  );
}

